import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';

// Vendor styles (same libraries the original template used)
// The template only relies on Bootstrap's Reboot layer (typography + resets)
import 'bootstrap/dist/css/bootstrap-reboot.min.css';
// Line Awesome + Phosphor, subset to the icons we use (generated by `npm run icons`)
import './styles/vendor/icons.css';

import './styles/index.css';
import App from './App';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
      <App />
    </BrowserRouter>
  </React.StrictMode>
);
